// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function _run(address receiver) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(receiver != address(0));
        uint balCBefore = address(c).balance;
        uint balTBefore = address(this).balance;
        bool reverted;
        try c.sendTo(receiver, 0) { reverted = false; }
        catch { reverted = true; }
        assertTrue(reverted && address(c).balance == balCBefore && address(this).balance == balTBefore);
    }

    function testFuzz_run(address receiver) public {
        vm.assume(receiver.code.length == 0 && uint160(receiver) > 0xffff && receiver != address(this) && receiver != address(c) && receiver != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && receiver != 0x000000000000000000636F6e736F6c652e6c6f67 && receiver != 0x4e59b44847b379578588920cA78FbF26c0B4956C && receiver != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(receiver);
    }

    receive() external payable {}
}
